VOWELS = frozenset("aeiou")


class VowelCounter:
    """Counts vowel occurrences in text, keeping per-vowel tallies."""

    def __init__(self, vowels=VOWELS):
        self.vowels = frozenset(v.lower() for v in vowels)
        self.tally = {v: 0 for v in sorted(self.vowels)}
        self.letters = 0

    def feed(self, text):
        for char in text:
            lowered = char.lower()
            if lowered.isalpha():
                self.letters += 1
            if lowered in self.vowels:
                self.tally[lowered] += 1
        return self

    def total(self):
        return sum(self.tally.values())

    def most_common(self):
        if not self.total():
            return None
        return max(self.tally, key=lambda v: (self.tally[v], -ord(v)))

    def density(self):
        if not self.letters:
            return 0.0
        return self.total() / self.letters

    def breakdown(self):
        return {v: n for v, n in self.tally.items() if n}


class VowelReport:
    """Formats the findings of a VowelCounter for a given sample."""

    def __init__(self, sample):
        self.sample = sample
        self.counter = VowelCounter().feed(sample)

    def headline(self):
        return "{!r}: {} vowel(s)".format(self.sample, self.counter.total())

    def detail_line(self):
        parts = ["{}={}".format(v, n) for v, n in self.counter.breakdown().items()]
        if not parts:
            return "  no vowels found"
        top = self.counter.most_common()
        return "  {} | top={} | density={:.2f}".format(
            ", ".join(parts), top, self.counter.density()
        )

    def render(self):
        return "\n".join([self.headline(), self.detail_line()])


def count_vowels(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return VowelCounter().feed(text).total()


def main():
    samples = ["Hello World", "Python", "AEIOU aeiou", "rhythm"]
    for sample in samples:
        print(VowelReport(sample).render())
    grand = sum(count_vowels(s) for s in samples)
    print("Grand total: {}".format(grand))


if __name__ == "__main__":
    main()

