def update_inventory(inventory, item_name, quantity):
    if item_name in inventory:
        inventory[item_name] += quantity
    else:
        inventory[item_name] = quantity
    return inventory


class TransactionLog:
    def __init__(self):
        self.entries = []

    def record(self, item_name, quantity, resulting_total):
        self.entries.append((item_name, quantity, resulting_total))
        return self.entries[-1]

    def net_change(self, item_name):
        return sum(q for name, q, _ in self.entries if name == item_name)

    def lines(self):
        for item_name, quantity, total in self.entries:
            sign = "+" if quantity >= 0 else "-"
            yield "%-10s %s%-4d -> %d" % (item_name, sign, abs(quantity), total)


class Inventory:
    def __init__(self, initial=None):
        self.items = dict(initial or {})
        self.log = TransactionLog()

    def add(self, item_name, quantity):
        if not isinstance(item_name, str) or not item_name.strip():
            raise ValueError("item name must be a non-empty string")
        if not isinstance(quantity, int):
            raise TypeError("quantity must be an integer")
        key = item_name.strip().lower()
        update_inventory(self.items, key, quantity)
        total = self.items[key]
        if total < 0:
            self.items[key] = total - quantity
            raise ValueError("stock for %r cannot go negative" % key)
        self.log.record(key, quantity, total)
        return total

    def remove(self, item_name, quantity):
        return self.add(item_name, -quantity)

    def stock_of(self, item_name):
        return self.items.get(item_name.strip().lower(), 0)

    def total_units(self):
        return sum(self.items.values())

    def report(self):
        rows = ["%-10s %d" % pair for pair in sorted(self.items.items())]
        footer = "%-10s %d" % ("TOTAL", self.total_units())
        header = "%-10s %s" % ("ITEM", "QTY")
        return "\n".join([header] + rows + [footer])

    def history(self):
        return "\n".join(self.log.lines())


def main():
    store = Inventory({'apple': 10})
    store.add('apple', 5)
    store.add('banana', 3)
    store.add('Cherry', 12)
    store.remove('cherry', 4)
    try:
        store.remove('banana', 99)
    except ValueError as exc:
        print("rejected:", exc)
    print(store.report())
    print("--- history ---")
    print(store.history())
    print("net apple change:", store.log.net_change('apple'))
    print("bananas on hand:", store.stock_of(' Banana '))


if __name__ == "__main__":
    main()

