        self.text = text
        self.raw_hashtags = []
        self.processed_hashtags = []

    def _find_raw_hashtags(self):
        self.raw_hashtags = re.findall(r'#(\w+)', self.text)

    def process_text_for_hashtags(self):
        self._find_raw_hashtags()
        processor = HashtagProcessor(self.raw_hashtags)
        self.processed_hashtags = processor.get_cleaned_hashtags()

    def get_extracted_hashtags(self):
