class HashtagProcessor:
    def __init__(self, raw_hashtags):
        self.raw_hashtags = raw_hashtags
        self.cleaned_hashtags = []

    def _clean_single_hashtag(self, hashtag):
        return hashtag.lower()

    def clean_hashtags(self):
        self.cleaned_hashtags = [self._clean_single_hashtag(h) for h in self.raw_hashtags]

    def get_cleaned_hashtags(self):
        self.clean_hashtags()
        return self.cleaned_hashtags

class Extractor:
    def __init__(self):
        self.last_processed_text = ""
        self.last_extracted_hashtags = []

