    def get_formatted_output(self):
        return list(self.sorted_data)

def sort_dict_by_value(d):
    if not d:
        return []
    processor = DictionaryProcessor(d)
    extracted = processor.extract_items()
    sorter = Sorter(extracted)
    sorted_result = sorter.perform_sort()
    formatter = OutputFormatter(sorted_result)
    return formatter.get_formatted_output()

