class TimeConverter:
    def __init__(self, total_seconds):
        self.total_seconds = total_seconds
        self.hours = 0
        self.minutes = 0
        self.seconds = 0

    def _calculate_hms(self):
        self.hours = self.total_seconds // 3600
        remaining_seconds = self.total_seconds % 3600
        self.minutes = remaining_seconds // 60
        self.seconds = remaining_seconds % 60

    def get_hms_values(self):
        self._calculate_hms()
        return self.hours, self.minutes, self.seconds

