    def __init__(self):
        pass

    def _pad(self, value):
        return f"{value:02d}"

    def format_time_components(self, hours, minutes, seconds):
        self.formatted_hours = self._pad(hours)
        self.formatted_minutes = self._pad(minutes)
        self.formatted_seconds = self._pad(seconds)
        return f"{self.formatted_hours}:{self.formatted_minutes}:{self.formatted_seconds}"

