class BinaryConverter:
    def __init__(self):
        self.result = ""

    def convert(self, decimal_int):
        if decimal_int == 0:
            self.result = "0"
            return self.result
        self.process_conversion(decimal_int)
        return self.result

    def process_conversion(self, n):
        temp_list = []
        while n > 0:
            remainder = n % 2
            temp_list.append(str(remainder))
            n //= 2
        temp_list.reverse()
        self.result = "".join(temp_list)

class NumberProcessor:
    def __init__(self):
        self.converter = BinaryConverter()

    def get_binary_string(self, decimal_value):
        self.check_input(decimal_value)
        return self.converter.convert(decimal_value)

    def check_input(self, value):
        if not isinstance(value, int) or value < 0:
            raise ValueError("Input must be a non-negative integer.")

class Solution:
    def __init__(self):
        self.processor = NumberProcessor()

    def decimal_to_binary(self, decimal_int):
        self.validate_integer(decimal_int)
        binary_output = self.processor.get_binary_string(decimal_int)
        return binary_output

    def validate_integer(self, number):
        if not isinstance(number, int):
            raise TypeError("Input must be an integer.")
        if number < 0:
            raise ValueError("Input must be non-negative.")

def decimal_to_binary(decimal_int):
