import math

class DataProcessor:
    def __init__(self, data_list):
        self.data = data_list

    def get_data(self):
        return self.data

    def calculate_mean(self):
        self.mean_value = sum(self.data) / len(self.data)
        return self.mean_value

class DeviationCalculator:
    def __init__(self, processor_instance):
        self.processor = processor_instance
        self.mean = self.processor.calculate_mean()

    def calculate_squared_deviations(self):
        self.deviations = [(x - self.mean) ** 2 for x in self.processor.get_data()]
        return self.deviations

class StandardDeviation:
    def __init__(self, deviation_calculator_instance):
        self.calculator = deviation_calculator_instance
        self.squared_deviations = self.calculator.calculate_squared_deviations()

    def calculate_sample_variance(self):
        self.n = len(self.calculator.processor.get_data())
        self.variance = sum(self.squared_deviations) / (self.n - 1)
        return self.variance

    def calculate_std_dev(self):
        self.std_dev_value = math.sqrt(self.calculate_sample_variance())
        return self.std_dev_value

def calculate_std_dev(numbers):
    processor = DataProcessor(numbers)
    deviations = DeviationCalculator(processor)
    std_dev_obj = StandardDeviation(deviations)
    return std_dev_obj.calculate_std_dev()

