class StringProcessor:
    def __init__(self):
        self.processed_string = ""

    def _normalize(self, input_string):
        self.processed_string = "".join(char for char in input_string if char.isalnum()).lower()
        return self.processed_string

class CharacterCounter:
    def __init__(self):
        self.counts = {}

    def _count_characters(self, normalized_string):
        self.counts = {}
        for char in normalized_string:
            self.counts[char] = self.counts.get(char, 0) + 1
        return self.counts

class AnagramChecker:
    def __init__(self):
        self.processor = StringProcessor()
        self.counter = CharacterCounter()

    def is_anagram(self, s1, s2):
        self.normalized_s1 = self.processor._normalize(s1)
        self.normalized_s2 = self.processor._normalize(s2)

        if len(self.normalized_s1) != len(self.normalized_s2):
            return False

        self.counts1 = self.counter._count_characters(self.normalized_s1)
        self.counts2 = self.counter._count_characters(self.normalized_s2)

        return self.counts1 == self.counts2

def is_anagram(s1, s2):
    checker = AnagramChecker()
    return checker.is_anagram(s1, s2)

