        self.start = start
        self.end = end

    def overlaps_with(self, other_event):
        self_overlaps_other_start = self.start < other_event.end
        self_overlaps_other_end = self.end > other_event.start
        return self_overlaps_other_start and self_overlaps_other_end

class Schedule:
    def __init__(self, events_data):
        self.events = [Event(s, e) for s, e in events_data]

    def has_any_conflict(self, new_event):
        for existing_event in self.events:
            if existing_event.overlaps_with(new_event):
                return True
        return False

