        self.current_schedule = Schedule(schedule_data)
        self.new_event = Event(new_event_start, new_event_end)
        self.result = self.current_schedule.has_any_conflict(self.new_event)
        return self.result

def has_conflict(schedule_data, new_event_start, new_event_end):
