        self.digit_processor = DigitProcessor(self.original_number)

    def is_armstrong(self):
        digits = self.digit_processor.get_digits()
        num_digits = self.digit_processor.get_num_digits()
        sum_of_powers = 0
        for digit in digits:
            power_calc = PowerCalculator(digit, num_digits)
            sum_of_powers += power_calc.calculate_power()
        return sum_of_powers == self.original_number

