class CaesarCipher:
    def __init__(self, shift_value):
        self.shift = shift_value
        self.alphabet_size = 26

    def _get_shifted_char_code(self, char_code):
        return (char_code - self.shift - ord('a') + self.alphabet_size) % self.alphabet_size + ord('a')

    def decrypt_char(self, char):
        if 'a' <= char <= 'z':
            original_code = ord(char)
            shifted_code = self._get_shifted_char_code(original_code)
            return chr(shifted_code)
        return char

class MessageProcessor:
    def __init__(self, cipher_engine):
        self.cipher = cipher_engine

    def process_message(self, text_to_process):
        decrypted_chars = []
        for char in text_to_process:
            decrypted_chars.append(self.cipher.decrypt_char(char))
        return "".join(decrypted_chars)

class Decryptor:
    def decrypt_caesar(self, text, shift):
        self.cipher_engine = CaesarCipher(shift)
        self.processor = MessageProcessor(self.cipher_engine)
        self.result = self.processor.process_message(text)
        return self.result

def decrypt_caesar(text, shift):
    my_decryptor = Decryptor()
    return my_decryptor.decrypt_caesar(text, shift)

