class DateParser:
    def __init__(self, date_string):
        self.date_string = date_string

    def parse_date(self):
        parts = self.date_string.split('-')
        self.year = int(parts[0])
        self.month = int(parts[1])
        self.day = int(parts[2])
        return self.year, self.month, self.day

class DateCalculator:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day
        self.days_in_month_list = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    def is_leap_year(self):
        return (self.year % 4 == 0 and self.year % 100 != 0) or (self.year % 400 == 0)

    def total_days_in_year(self):
        total_days = 0
        for m in range(1, self.month):
            total_days += self.days_in_month_list[m]
            if m == 2 and self.is_leap_year():
                total_days += 1
        total_days += self.day - 1
        return total_days

class EpochCounter:
    def __init__(self, target_year, target_month, target_day):
        self.epoch_year = 1970
        self.target_year = target_year
        self.target_month = target_month
        self.target_day = target_day

    def calculate_days(self):
        days_count = 0
        for y in range(self.epoch_year, self.target_year):
            self.current_year_calculator = DateCalculator(y, 1, 1)
            days_count += 366 if self.current_year_calculator.is_leap_year() else 365
        self.target_date_calculator = DateCalculator(self.target_year, self.target_month, self.target_day)
        days_count += self.target_date_calculator.total_days_in_year()
        return days_count

def days_since_epoch(date_str):
    parser = DateParser(date_str)
    year, month, day = parser.parse_date()
    counter = EpochCounter(year, month, day)
    return counter.calculate_days()

