    def simulate_stack(self, stack_list, operation, item=None):
        manager = StackManager(stack_list)
        ops = StackOperations(manager)

        if operation == 'push':
            return ops.perform_push(item)
        elif operation == 'pop':
            return ops.perform_pop()
        else:
            raise ValueError(f"Unknown operation: {operation}")

_simulator = StackSimulator()
simulate_stack = _simulator.simulate_stack

