class DataProcessor:
    def __init__(self, values, weights):
        self.values = values
        self.weights = weights

    def get_weighted_sum(self):
        self.weighted_products = [v * w for v, w in zip(self.values, self.weights)]
        return sum(self.weighted_products)

class WeightCalculator:
    def __init__(self, weights):
        self.weights = weights

    def get_total_weight(self):
        return sum(self.weights)

class Averager:
    def __init__(self, processor, calculator):
        self.processor = processor
        self.calculator = calculator

    def calculate_average(self):
        self.sum_products = self.processor.get_weighted_sum()
        self.total_weight = self.calculator.get_total_weight()
        if self.total_weight == 0:
            return 0.0
        return self.sum_products / self.total_weight

def weighted_average(values, weights):
    processor = DataProcessor(values, weights)
    calculator = WeightCalculator(weights)
    averager = Averager(processor, calculator)
    return averager.calculate_average()

