class DigitExtractor:
    def __init__(self, number):
        self.number = number
        self.digits = []

    def extract(self):
        temp = self.number
        if temp == 0:
            self.digits.append(0)
            return self.digits
        while temp > 0:
            self.digits.append(temp % 10)
            temp //= 10
        return self.digits

class DigitSorter:
    def __init__(self, digits):
        self.digits = digits

    def sort(self):
        self.digits.sort()
        return self.digits

class NumberConstructor:
    def __init__(self, sorted_digits):
        self.sorted_digits = sorted_digits
        self.result = 0

    def construct(self):
        for digit in self.sorted_digits:
            self.result = self.result * 10 + digit
        return self.result

def sort_digits(number):
    extractor = DigitExtractor(number)
    extracted_digits = extractor.extract()
    sorter = DigitSorter(extracted_digits)
    sorted_digits = sorter.sort()
    constructor = NumberConstructor(sorted_digits)
    return constructor.construct()

