class DivisibilityChecker:
    def __init__(self, number):
        self.number = number
        self.result_3 = False
        self.result_5 = False

    def check_divisibility_by_3(self):
        self.result_3 = (self.number % 3 == 0)
        return self.result_3

    def check_divisibility_by_5(self):
        self.result_5 = (self.number % 5 == 0)
        return self.result_5

class CombinedChecker:
    def __init__(self, checker_3, checker_5):
        self.checker_3 = checker_3
        self.checker_5 = checker_5
        self.overall_result = False

    def perform_combined_check(self):
        self.checker_3.check_divisibility_by_3()
        self.checker_5.check_divisibility_by_5()
        self.overall_result = self.checker_3.result_3 and self.checker_5.result_5
        return self.overall_result

class ResultPresenter:
    def __init__(self, combined_checker_instance):
        self.combined_checker_instance = combined_checker_instance
        self.final_answer = False

    def present_result(self):
        self.final_answer = self.combined_checker_instance.perform_combined_check()
        return self.final_answer

def is_divisible_by_3_and_5(number):
    checker_for_3 = DivisibilityChecker(number)
    checker_for_5 = DivisibilityChecker(number)
    combined = CombinedChecker(checker_for_3, checker_for_5)
    presenter = ResultPresenter(combined)
    return presenter.present_result()

