        self.number = number

    def calculate_product(self, factor):
        return self.number * factor

class Formatter:
    def __init__(self, number):
        self.number = number

    def format_entry(self, factor, product):
        return f"{self.number} x {factor} = {product}"

class TimesTableGenerator:
    def __init__(self, number, limit):
        self.number = number
        self.limit = limit
        self.multiplier = Multiplier(self.number)
        self.formatter = Formatter(self.number)
        self.table_list = []

    def generate_table(self):
        for factor in range(1, self.limit + 1):
            product = self.multiplier.calculate_product(factor)
            formatted_string = self.formatter.format_entry(factor, product)
            self.table_list.append(formatted_string)
        return self.table_list

def generate_times_table(number, limit):
    generator = TimesTableGenerator(number, limit)
    return generator.generate_table()

