class TimeConverter:
    def __init__(self, total_minutes):
        self.total_minutes = total_minutes
        self.hours = 0
        self.minutes = 0

    def calculate_components(self):
        self.hours = self.total_minutes // 60
        self.minutes = self.total_minutes % 60
        return self.hours, self.minutes

class Formatter:
    def __init__(self, hours, minutes):
        self.hours = hours
        self.minutes = minutes
        self.formatted_string = ""

    def format_time(self):
        self.formatted_string = f"{self.hours:02d}:{self.minutes:02d}"
        return self.formatted_string

class TimeProcessor:
    def __init__(self, total_minutes):
        self.total_minutes = total_minutes
        self.converter = TimeConverter(self.total_minutes)
        self.formatter = None

    def process(self):
        hours, minutes = self.converter.calculate_components()
        self.formatter = Formatter(hours, minutes)
        return self.formatter.format_time()

def minutes_to_hh_mm(total_minutes):
    processor = TimeProcessor(total_minutes)
    return processor.process()

