class BracketChecker:
    def __init__(self):
        self.stack = []
        self.bracket_map = {')': '(', ']': '[', '}': '{'}

    def is_opening(self, char):
        return char in self.bracket_map.values()

    def is_closing(self, char):
        return char in self.bracket_map.keys()

    def push(self, char):
        self.stack.append(char)

    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        return None

    def is_empty(self):
        return len(self.stack) == 0

class BracketProcessor:
    def __init__(self):
        self.checker = BracketChecker()

    def process_char(self, char):
        if self.checker.is_opening(char):
            self.checker.push(char)
        elif self.checker.is_closing(char):
            if self.checker.is_empty() or self.checker.pop() != self.checker.bracket_map[char]:
                return False
        return True

    def check_final_state(self):
        return self.checker.is_empty()

class Solution:
    def is_brackets_balanced(self, s: str) -> bool:
        processor = BracketProcessor()
        for char in s:
            if not processor.process_char(char):
                return False
        return processor.check_final_state()

