    def __init__(self, numbers_list):
        self.numbers = numbers_list
        self.max_val = None
        self.min_val = None

    def find_max(self):
        if not self.numbers:
            self.max_val = None
            return None
        self.max_val = self.numbers[0]
        for num in self.numbers:
            if num > self.max_val:
                self.max_val = num
        return self.max_val

    def find_min(self):
        if not self.numbers:
            self.min_val = None
            return None
        self.min_val = self.numbers[0]
        for num in self.numbers:
            if num < self.min_val:
                self.min_val = num
        return self.min_val

