    def __init__(self, analyzer):
        self.analyzer = analyzer
        self.calculated_range = 0

    def calculate(self):
        max_num = self.analyzer.find_max()
        min_num = self.analyzer.find_min()

        if max_num is None or min_num is None:
            self.calculated_range = 0
            return 0
        self.calculated_range = max_num - min_num
        return self.calculated_range

