class RomanConverter:
    def __init__(self):
        self.mapping = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'),
                        (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'),
                        (5, 'V'), (4, 'IV'), (1, 'I')]
        self.result = ""

    def append_symbol(self, count, symbol):
        self.result += symbol * count

    def convert(self, num):
        self.current_num = num
        for value, symbol in self.mapping:
            while self.current_num >= value:
                self.append_symbol(1, symbol)
                self.current_num -= value
        return self.result

