class Meeting:
    def __init__(self, start, end, label=None):
        if start > end:
            raise ValueError("meeting start must not exceed its end")
        self.start = start
        self.end = end
        self.label = label or "meeting"

    @classmethod
    def from_tuple(cls, interval, label=None):
        start, end = interval
        return cls(int(start), int(end), label)

    def overlaps(self, other):
        return self.start < other.end and other.start < self.end

    def overlap_minutes(self, other):
        if not self.overlaps(other):
            return 0
        return min(self.end, other.end) - max(self.start, other.start)

    def duration(self):
        return self.end - self.start

    def __str__(self):
        return "{} [{}, {})".format(self.label, self.start, self.end)


class Schedule:
    def __init__(self, owner):
        self.owner = owner
        self.meetings = []

    def add(self, interval, label=None):
        meeting = Meeting.from_tuple(interval, label)
        self.meetings.append(meeting)
        return meeting

    def conflicts(self):
        ordered = sorted(self.meetings, key=lambda m: (m.start, m.end))
        found = []
        for index, current in enumerate(ordered):
            for later in ordered[index + 1:]:
                if later.start >= current.end:
                    break
                found.append((current, later, current.overlap_minutes(later)))
        return found

    def busy_minutes(self):
        return sum(meeting.duration() for meeting in self.meetings)

    def report(self):
        lines = ["Schedule for {} ({} meetings, {} busy minutes)".format(
            self.owner, len(self.meetings), self.busy_minutes())]
        for meeting in sorted(self.meetings, key=lambda m: m.start):
            lines.append("  " + str(meeting))
        problems = self.conflicts()
        if not problems:
            lines.append("  no conflicts")
        for first, second, shared in problems:
            lines.append("  conflict: {} vs {} ({} min)".format(
                first.label, second.label, shared))
        return "\n".join(lines)


def has_overlap(meeting1, meeting2):
    first = Meeting.from_tuple(meeting1)
    second = Meeting.from_tuple(meeting2)
    return first.overlaps(second)


def main():
    print(has_overlap((1, 5), (3, 7)))
    print(has_overlap((1, 2), (3, 4)))

    day = Schedule("Ada")
    day.add((9, 10), "standup")
    day.add((9, 11), "design review")
    day.add((13, 14), "1:1")
    print(day.report())


if __name__ == "__main__":
    main()

