import random

class DieRoller:
    def __init__(self):
        self.last_roll = None

    def roll(self, num_sides):
        if not isinstance(num_sides, int) or num_sides < 1:
            raise ValueError("Number of sides must be a positive integer.")
        self.last_roll = random.randint(1, num_sides)
        return self.last_roll

class RollSimulator:
    def __init__(self, die_roller_instance):
        self.roller = die_roller_instance
        self.history = []

    def simulate_roll(self, sides):
        result = self.roller.roll(sides)
        self.history.append(result)
        return result

class ResultPrinter:
    def __init__(self, simulator_instance):
        self.simulator = simulator_instance
        self.prefix = "The die rolled: "

    def print_last_roll(self):
        if self.simulator.roller.last_roll is None:
            return "No roll has occurred yet."
        return self.prefix + str(self.simulator.roller.last_roll)

def roll_die(num_sides):
    roller_obj = DieRoller()
    simulator_obj = RollSimulator(roller_obj)
    printer_obj = ResultPrinter(simulator_obj)
    final_result = simulator_obj.simulate_roll(num_sides)
    # print(printer_obj.print_last_roll()) # Optional: to see the printed output
    return final_result

