    def __init__(self, matrix):
        self.matrix = matrix

    def get_num_rows(self):
        return len(self.matrix)

    def get_num_cols(self):
        if not self.matrix:
            return 0
        return len(self.matrix[0])

class Transposer:
    def __init__(self, processor):
        self.processor = processor

    def create_empty_transposed_matrix(self):
        rows = self.processor.get_num_rows()
        cols = self.processor.get_num_cols()
        return [[0 for _ in range(rows)] for _ in range(cols)]

    def perform_transpose(self):
        original_matrix = self.processor.matrix
        transposed = self.create_empty_transposed_matrix()
        num_rows = self.processor.get_num_rows()
        num_cols = self.processor.get_num_cols()
        for i in range(num_rows):
            for j in range(num_cols):
                transposed[j][i] = original_matrix[i][j]
        return transposed

class MatrixOperations:
    def transpose_matrix(self, matrix):
        processor = MatrixProcessor(matrix)
        transposer = Transposer(processor)
        return transposer.perform_transpose()

