        return max(self.numbers)

    def get_sum(self):
        return sum(self.numbers)

class MissingNumberFinder:
    def __init__(self, number_list_obj):
        self.number_list = number_list_obj

    def calculate_expected_sum(self):
        n = self.number_list.get_max_value() + 1
        return n * (n + 1) // 2

    def find_missing(self):
        expected_sum = self.calculate_expected_sum()
        actual_sum = self.number_list.get_sum()
        return expected_sum - actual_sum

class Solution:
    def find_missing_number(self, numbers):
        self.number_list_instance = NumberList(numbers)
        self.finder_instance = MissingNumberFinder(self.number_list_instance)
        return self.finder_instance.find_missing()

def find_missing_number(numbers):
    solver = Solution()
    return solver.find_missing_number(numbers)

