class FinancialInstrument:
    def __init__(self, principal, rate, compounding_frequency, time_years):
        self.principal = principal
        self.rate = rate
        self.compounding_frequency = compounding_frequency
        self.time_years = time_years

    def get_principal(self):
        return self.principal

    def get_annual_rate(self):
        return self.rate

    def get_compounding_frequency(self):
        return self.compounding_frequency

    def get_time_in_years(self):
        return self.time_years

class CompoundInterestCalculator:
    def calculate_amount(self, instrument):
        n = instrument.get_compounding_frequency()
        t = instrument.get_time_in_years()
        r = instrument.get_annual_rate()
        p = instrument.get_principal()
        amount = p * (1 + r / n)**(n * t)
        self.last_calculated_amount = amount
        return self.last_calculated_amount

class FinancialReporter:
    def __init__(self):
        self.report_data = {}

    def add_result(self, instrument, amount):
        self.report_data[instrument.get_principal()] = amount
        self.last_added_principal = instrument.get_principal()

def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    instrument = FinancialInstrument(principal, rate, compounding_frequency, time_years)
    calculator = CompoundInterestCalculator()
    total_amount = calculator.calculate_amount(instrument)
    reporter = FinancialReporter()
    reporter.add_result(instrument, total_amount)
    return total_amount

