class MatrixElement:
    def __init__(self, value):
        self.value = value

    def get_value(self):
        return self.value

class MatrixRow:
    def __init__(self, elements):
        self.elements = [MatrixElement(e) for e in elements]

    def get_element(self, index):
        return self.elements[index].get_value()

class Matrix:
    def __init__(self, data):
        self.rows = [MatrixRow(row) for row in data]

    def get_row(self, index):
        return self.rows[index]

    def get_element_at(self, row_idx, col_idx):
        return self.get_row(row_idx).get_element(col_idx)

    def multiply(self, other_matrix):
        result_data = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                sum_val = 0
                for k in range(2):
                    sum_val += self.get_element_at(i, k) * other_matrix.get_element_at(k, j)
                result_data[i][j] = sum_val
        return Matrix(result_data).to_list()

    def to_list(self):
        return [[elem.get_value() for elem in row.elements] for row in self.rows]

def multiply_2x2_matrices(matrix_a, matrix_b):
    a = Matrix(matrix_a)
    b = Matrix(matrix_b)
    return a.multiply(b)

