class Window:
    def __init__(self, size):
        self.size = size
        self.elements = []
        self.current_sum = 0.0

    def add_element(self, value):
        self.elements.append(value)
        self.current_sum += value
        if len(self.elements) > self.size:
            self.current_sum -= self.elements.pop(0)

    def is_full(self):
        return len(self.elements) == self.size

    def calculate_average(self):
        if not self.is_full():
            return None
        return self.current_sum / self.size

class MovingAverageCalculator:
    def __init__(self, window_size):
        self.window_size = window_size
        self.window = Window(window_size)
        self.results = []

    def process_data_point(self, data_point):
        self.window.add_element(data_point)
        if self.window.is_full():
            self.results.append(self.window.calculate_average())

    def get_averages(self):
        return self.results

class SMASolver:
    def solve(self, data, window_size):
        calculator = MovingAverageCalculator(window_size)
        for point in data:
            calculator.process_data_point(point)
        return calculator.get_averages()

def calculate_sma(data, window_size):
    solver = SMASolver()
    return solver.solve(data, window_size)

