class DivisorCalculator:
    def __init__(self, number):
        self.number = number
        self.divisors = []

    def find_proper_divisors(self):
        for i in range(1, self.number // 2 + 1):
            if self.number % i == 0:
                self.divisors.append(i)
        return self.divisors

class SummationEngine:
    def __init__(self):
        self.total_sum = 0

    def add_list_elements(self, numbers):
        for num in numbers:
            self.total_sum += num
        return self.total_sum

class PerfectNumberChecker:
    def __init__(self, number):
        self.number_to_check = number
        self.calculator = DivisorCalculator(self.number_to_check)
        self.engine = SummationEngine()

    def is_perfect_number(self):
        if self.number_to_check <= 0:
            return False

        proper_divs = self.calculator.find_proper_divisors()
        sum_of_divs = self.engine.add_list_elements(proper_divs)

        return sum_of_divs == self.number_to_check

def is_perfect_number(number):
    checker = PerfectNumberChecker(number)
    return checker.is_perfect_number()

