class BinaryConverter:
    def __init__(self, binary_string):
        self.binary_string = binary_string
        self.decimal_value = 0

    def _convert_digit(self, digit, power):
        if digit == '1':
            self.decimal_value += 2 ** power

    def convert(self):
        self.decimal_value = 0
        length = len(self.binary_string)
        for i, digit in enumerate(self.binary_string):
            self._convert_digit(digit, length - 1 - i)
        return self.decimal_value

