        elif self.from_unit == 'ft' and self.to_unit == 'm':
            return self.length_processor.feet_to_meters(self.value)
        elif self.from_unit == self.to_unit:
            return self.value
        else:
            raise ValueError("Invalid unit conversion specified by self.")

def convert_length(value, from_unit, to_unit):
    converter_instance = LengthConverter()
