class PowerCalculator:
    def __init__(this, base, exponent):
        this.base = base
        this.exponent = exponent
        this.result = None

    def _calculate_positive_power(this):
        this.result = 1
        for _ in range(this.exponent):
            this.result *= this.base
        return this.result

    def calculate(this):
        if this.exponent == 0:
            this.result = 1
        elif this.exponent > 0:
            this.result = this._calculate_positive_power()
        else:
            raise ValueError("Exponent must be non-negative for this implementation.")
        return this.result

