import datetime

class DateCalculator:
    def __init__(self):
        self.today = datetime.date.today()

    def calculate_difference(self, start_date):
        self.delta = self.today - start_date
        return self.delta.days

class DateParser:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day

    def create_date_object(self):
        self.parsed_date = datetime.date(self.year, self.month, self.day)
        return self.parsed_date

class DateHandler:
    def __init__(self):
        self.parser = None
        self.calculator = DateCalculator()

    def set_date(self, year, month, day):
        self.parser = DateParser(year, month, day)
        self.start_date = self.parser.create_date_object()

    def get_days_since(self):
        if self.parser is None:
            raise ValueError("Date not set. Call set_date() first.")
        self.result = self.calculator.calculate_difference(self.start_date)
        return self.result

def days_since(year, month, day):
    handler = DateHandler()
    handler.set_date(year, month, day)
    return handler.get_days_since()

