class CsvLineParser:
    def __init__(self):
        self.delimiter = ','
        self.empty_field_marker = ''

    def parse(self, line):
        self.current_line = line
        self.fields = self.current_line.split(self.delimiter)
        return self.fields

class FieldProcessor:
    def __init__(self, raw_fields):
        self.raw_fields = raw_fields
        self.processed_fields = []

    def process_all(self):
        for field in self.raw_fields:
            self.processed_fields.append(self._process_single_field(field))
        return self.processed_fields

    def _process_single_field(self, field_value):
        if not field_value:
            return ""
        return field_value

class CsvHandler:
    def __init__(self):
        self.parser = CsvLineParser()
        self.field_processor = None

    def parse_csv_line(self, line):
        self.parsed_raw_fields = self.parser.parse(line)
        self.field_processor = FieldProcessor(self.parsed_raw_fields)
        self.final_fields = self.field_processor.process_all()
        return self.final_fields

def parse_csv_line(line):
    handler = CsvHandler()
    return handler.parse_csv_line(line)

