class TransactionProcessor:
    def process_deposit(self, account_obj, amount_val):
        if amount_val > 0:
            account_obj.balance_field += amount_val
            return True
        self.last_error = "Deposit amount must be positive."
        return False

    def process_withdrawal(self, account_obj, amount_val):
        if amount_val > 0:
            if account_obj.balance_field >= amount_val:
                account_obj.balance_field -= amount_val
                return True
            self.last_error = "Insufficient funds."
            return False
        self.last_error = "Withdrawal amount must be positive."
        return False

class BankAccount:
    def __init__(self, initial_balance_val):
        if initial_balance_val >= 0:
            self.balance_field = initial_balance_val
        else:
            self.balance_field = 0
            self.creation_error = "Initial balance cannot be negative; set to zero."
        self.processor_instance = TransactionProcessor()
        self.transaction_history = []
        self.account_id = id(self)
        self.is_active = True

    def deposit(self, amount_to_deposit):
        result = self.processor_instance.process_deposit(self, amount_to_deposit)
        if result:
            self.transaction_history.append(f"Deposit: {amount_to_deposit}")
            self.last_transaction_successful = True
        else:
            self.last_transaction_successful = False
        return result

    def withdraw(self, amount_to_withdraw):
        result = self.processor_instance.process_withdrawal(self, amount_to_withdraw)
        if result:
            self.transaction_history.append(f"Withdraw: {amount_to_withdraw}")
            self.last_transaction_successful = True
        else:
            self.last_transaction_successful = False
        return result

class AccountManager:
    def __init__(self):
        self.accounts_list = []
        self.next_account_number = 1000
        self.manager_status = "Operational"

    def create_new_account(self, initial_amount):
        new_account = BankAccount(initial_amount)
        self.accounts_list.append(new_account)
        new_account.account_number = self.next_account_number
        self.next_account_number += 1
        new_account.manager_ref = self
        return new_account

    def get_account_balance(self, account_obj):
        if account_obj in self.accounts_list:
            self.last_retrieval_status = "Success"
            return account_obj.balance_field
        self.last_retrieval_status = "Account not found"
        return None

