        self.inventory = initial_inventory

    def get_inventory(self):
        return self.inventory

    def set_inventory(self, new_inventory):
        self.inventory = new_inventory

class ItemUpdater:
    def __init__(self, manager):
        self.manager = manager

    def process_change(self, item_name, quantity_change):
        current_inventory = self.manager.get_inventory()
        updater = QuantityCalculator(current_inventory.get(item_name, 0), quantity_change)
        new_quantity = updater.calculate_new_quantity()
        current_inventory[item_name] = new_quantity
        self.manager.set_inventory(current_inventory)
        return self.manager.get_inventory()

class QuantityCalculator:
    def __init__(self, current_quantity, change):
        self.current_quantity = current_quantity
        self.change = change

    def calculate_new_quantity(self):
        self.new_raw_quantity = self.current_quantity + self.change
        if self.new_raw_quantity < 0:
            self.final_quantity = 0
        else:
            self.final_quantity = self.new_raw_quantity
        return self.final_quantity

def update_inventory(inventory, item_name, quantity_change):
    manager = InventoryManager(inventory)
    updater = ItemUpdater(manager)
    return updater.process_change(item_name, quantity_change)

