class Calculator:
    def __init__(self, data):
        self.data = data

    def calculate_mean(self):
        if not self.data:
            return 0.0
        self.total_sum = sum(self.data)
        self.count = len(self.data)
        return self.total_sum / self.count

class DeviationCalculator:
    def __init__(self, numbers):
        self.numbers = numbers
        self.calculator = Calculator(numbers)

    def calculate_absolute_deviations(self):
        self.mean_val = self.calculator.calculate_mean()
        if not self.numbers:
            return []
        self.deviations = [abs(num - self.mean_val) for num in self.numbers]
        return self.deviations

