import random

class Guesser:
    def __init__(self, min_val, max_val):
        self.min_val = min_val
        self.max_val = max_val

    def make_guess(self):
        return random.randint(self.min_val, self.max_val)

class GameState:
    def __init__(self, target, max_guesses):
        self.target = target
        self.max_guesses = max_guesses
        self.guesses_taken = 0

    def record_guess(self):
        self.guesses_taken += 1
        return self.guesses_taken

    def is_game_over(self):
        return self.guesses_taken >= self.max_guesses

    def is_target_found(self, guess):
        return guess == self.target

class Game:
    def __init__(self, target, max_guesses):
        self.guesser = Guesser(1, 100)
        self.state = GameState(target, max_guesses)

    def play(self):
        while not self.state.is_game_over():
            current_guess = self.guesser.make_guess()
            self.state.record_guess()
            if self.state.is_target_found(current_guess):
                return self.state.guesses_taken
        return -1

def play_guessing_game(target, max_guesses):
    game_instance = Game(target, max_guesses)
    return game_instance.play()

