class TriangleValidator:
    def __init__(self):
        self.validation_result = False

    def is_valid(self, a, b, c):
        self.validation_result = (a + b > c) and (a + c > b) and (b + c > a)
        return self.validation_result

class TriangleCalculator:
    def __init__(self, a, b, c):
        self.side_a = a
        self.side_b = b
        self.side_c = c
        self.semi_perimeter = 0.0
        self.area = 0.0

    def calculate_semi_perimeter(self):
        self.semi_perimeter = (self.side_a + self.side_b + self.side_c) / 2
        return self.semi_perimeter

    def calculate_area(self):
        s = self.calculate_semi_perimeter()
        self.area = (s * (s - self.side_a) * (s - self.side_b) * (s - self.side_c)) ** 0.5
        return self.area

class TriangleAreaSolver:
    def __init__(self):
        self.validator = TriangleValidator()
        self.calculator = None
        self.final_area = 0.0

    def solve(self, a, b, c):
        if not self.validator.is_valid(a, b, c):
            self.final_area = 0.0
            return self.final_area
        self.calculator = TriangleCalculator(a, b, c)
        self.final_area = self.calculator.calculate_area()
        return self.final_area

def triangle_area(a, b, c):
    solver = TriangleAreaSolver()
    return solver.solve(a, b, c)

