class Calculator:
    def __init__(self):
        self.result = 1.0
        self.count = 0

    def multiply(self, number):
        self.result *= number
        self.count += 1
        return self.result

    def power(self, exponent):
        if self.count == 0:
            return 0.0
        self.result = self.result ** exponent
        return self.result

    def get_result(self):
        return self.result

class ListValidator:
    def __init__(self):
        self.valid = True

    def check_positive(self, numbers):
        for number in numbers:
            if not isinstance(number, (int, float)) or number <= 0:
                self.valid = False
                break
        return self.valid

    def is_valid(self):
        return self.valid

class GeometricMeanProcessor:
    def __init__(self):
        self.calculator = Calculator()
        self.validator = ListValidator()

    def calculate(self, numbers):
        if not numbers:
            return 0.0
        if not self.validator.check_positive(numbers):
            return 0.0

        for num in numbers:
            self.calculator.multiply(num)

        power_val = 1.0 / len(numbers)
        self.calculator.power(power_val)
        return self.calculator.get_result()

def geometric_mean(numbers):
    processor = GeometricMeanProcessor()
    return processor.calculate(numbers)

