class Matrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = [[0 for _ in range(cols)] for _ in range(rows)]

    def get_value(self, r, c):
        return self.data[r][c]

    def set_value(self, r, c, value):
        self.data[r][c] = value

class LevenshteinCalculator:
    def __init__(self, s1, s2):
        self.s1 = s1
        self.s2 = s2
        self.len_s1 = len(s1)
        self.len_s2 = len(s2)
        self.dp_matrix = Matrix(self.len_s1 + 1, self.len_s2 + 1)

    def calculate_distance(self):
        for i in range(self.len_s1 + 1):
            self.dp_matrix.set_value(i, 0, i)
        for j in range(self.len_s2 + 1):
            self.dp_matrix.set_value(0, j, j)

        for i in range(1, self.len_s1 + 1):
            for j in range(1, self.len_s2 + 1):
                cost = 0 if self.s1[i - 1] == self.s2[j - 1] else 1
                insertion = self.dp_matrix.get_value(i, j - 1) + 1
                deletion = self.dp_matrix.get_value(i - 1, j) + 1
                substitution = self.dp_matrix.get_value(i - 1, j - 1) + cost
                self.dp_matrix.set_value(i, j, min(insertion, deletion, substitution))
        return self.dp_matrix.get_value(self.len_s1, self.len_s2)

class LevenshteinProcessor:
    def process(self, s1, s2):
        calculator = LevenshteinCalculator(s1, s2)
        return calculator.calculate_distance()

def levenshtein_distance(s1, s2):
    processor = LevenshteinProcessor()
    return processor.process(s1, s2)

