class XORCipherMachine:
    def __init__(self):
        self.current_cipher = None

    def set_cipher_key(self, key_char):
        self.current_cipher = Cipher(key_char)

    def encrypt_decrypt(self, text):
        if not self.current_cipher:
            raise ValueError("Key not set for cipher machine.")
        text_obj = TextProcessor(text)
        processed_text = self.current_cipher.process_text(text_obj.get_text())
        text_obj.set_text(processed_text)
        return text_obj.get_text()

def xor_cipher(text, key_char):
    machine = XORCipherMachine()
    machine.set_cipher_key(key_char)
