        self.target_unit = unit_to
        self.result = self.main_converter.convert(self.input_value, self.source_unit, self.target_unit)
        return self.result

def convert_temperature(value, unit_from, unit_to):
    processor = TemperatureProcessor()
    return processor.process_conversion(value, unit_from, unit_to)

