    def starts_with_prefix(self, code):
        self.code = code
        return self.code.startswith(self.prefix)

class HexDigitChecker:
    def __init__(self):
        self.hex_chars = "0123456789abcdefABCDEF"

    def contains_only_hex_digits(self, s):
        self.s = s
        for char in self.s:
            if char not in self.hex_chars:
                return False
        return True

