class PasswordChecker:
    def __init__(self, password):
        self.password = password
        self.length = len(password)

    def _has_uppercase(self):
        return any(c.isupper() for c in self.password)

    def _has_lowercase(self):
        return any(c.islower() for c in self.password)

    def _has_digit(self):
        return any(c.isdigit() for c in self.password)

    def _count_char_types(self):
        count = 0
        if self._has_uppercase():
            count += 1
        if self._has_lowercase():
            count += 1
        if self._has_digit():
            count += 1
        return count

class StrengthEvaluator:
    def __init__(self, checker):
        self.checker = checker
        self.length = checker.length
        self.char_types = checker._count_char_types()

    def evaluate(self):
        if self.length >= 8 and self.char_types == 3:
            return 'Strong'
        elif self.length >= 6 and self.char_types >= 2:
            return 'Medium'
        else:
            return 'Weak'

