class PermutationGenerator:
    def __init__(self, initial_list):
        self.initial_list = initial_list
        self.results = []
        self.helper_instance = PermutationHelper(self)

    def generate(self):
        self.helper_instance.compute_permutations_recursive(self.initial_list, [])
        return self.results

    def add_result(self, perm):
        self.results.append(perm)

class PermutationHelper:
    def __init__(self, generator_instance):
        self.generator_instance = generator_instance
        self.processor_instance = PermutationProcessor(self)

    def compute_permutations_recursive(self, remaining_elements, current_permutation):
        if not remaining_elements:
