class HashGenerator:
    def __init__(self, accumulator_instance):
        self.accumulator = accumulator_instance
        self.generator_initialized = True
        self.hash_computed_times = 0

    def compute_hash(self, input_string):
        if not self.generator_initialized:
            raise RuntimeError("Generator not initialized.")
        char_processor = CharacterProcessor()
        for char in input_string:
            char_val = char_processor.process_char(char)
            self.accumulator.add_value(char_val)
        self.hash_computed_times += 1
        return self.accumulator.get_total_sum()

    def reset_accumulator(self):
        self.accumulator.current_sum = 0
        self.accumulator.updates_count = 0
        self.accumulator.last_added = 0

def simple_hash(s):
    accumulator_instance = StringAccumulator()
    hash_generator = HashGenerator(accumulator_instance)
    result = hash_generator.compute_hash(s)
    hash_generator.reset_accumulator()
    return result

