import re

class WordProcessor:
    def __init__(self):
        self.punctuation_pattern = re.compile(r"([.,!?;:]+)$")

    def split_into_words_and_punctuation(self, word_with_punct):
        match = self.punctuation_pattern.search(word_with_punct)
        if match:
            self.punctuation = match.group(1)
            self.word = word_with_punct[:match.start()]
        else:
            self.punctuation = ""
            self.word = word_with_punct
        return self.word, self.punctuation

    def join_word_and_punctuation(self, word, punctuation):
        self.combined_word = f"{word}{punctuation}"
        return self.combined_word

    def process_single_word(self, word_text):
        main_word, punct = self.split_into_words_and_punctuation(word_text)
        return self.join_word_and_punctuation(main_word, punct)

    def get_punctuation_pattern(self):
        return self.punctuation_pattern

    def check_for_punctuation(self, text):
        return bool(self.punctuation_pattern.search(text))

    def extract_word_only(self, text):
        match = self.punctuation_pattern.search(text)
        if match:
            return text[:match.start()]
        return text

