    def __init__(self):
        self.word_processor = WordProcessor()

    def split_sentence_into_words(self, sentence):
        self.words = sentence.split(' ')
        return self.words

    def reverse_word_list(self, word_list):
        self.reversed_words = word_list[::-1]
        return self.reversed_words

    def process_and_join_words(self, words):
        processed_words = []
        for word in words:
            processed_words.append(self.word_processor.process_single_word(word))
        self.final_sentence = " ".join(processed_words)
        return self.final_sentence

    def get_word_processor(self):
        return self.word_processor

    def get_words_after_split(self):
        return self.words

    def get_reversed_words(self):
        return self.reversed_words

    def get_final_sentence(self):
        return self.final_sentence

