        self.filepath = filepath
        self.content = ""

    def read_file_content(self):
        try:
            with open(self.filepath, 'r') as self.file:
                self.content = self.file.read()
                return self.content
        except FileNotFoundError:
            self.content = ""
            return ""

    def get_content_length(self):
        return len(self.content)

class WordExtractor:
    def __init__(self, text):
        self.text = text
        self.words = []

    def extract_alphanumeric_words(self):
        import re
        self.words = re.findall(r'\b[a-zA-Z0-9]+\b', self.text)
        return self.words

    def get_word_count(self):
        return len(self.words)

    def is_empty(self):
        return not self.words

    def get_first_word(self):
        return self.words[0] if self.words else ""

    def get_last_word(self):
        return self.words[-1] if self.words else ""

class LongestWordFinder:
    def __init__(self):
        self.longest_word = ""

    def find_longest(self, words):
        self.longest_word = ""
        for self.word in words:
            if len(self.word) > len(self.longest_word):
                self.longest_word = self.word
        return self.longest_word

    def get_current_longest_word(self):
        return self.longest_word

    def reset_longest_word(self):
        self.longest_word = ""

