    reader = FileReader(filepath)
    file_content = reader.read_file_content()

    if not file_content:
        return ""

    extractor = WordExtractor(file_content)
    words = extractor.extract_alphanumeric_words()

    if extractor.is_empty():
        return ""

    finder = LongestWordFinder()
    longest = finder.find_longest(words)
    return longest

