class FactorialCalculator:
    def __init__(self):
        self.memo = {0: 1, 1: 1}

    def _recursive_factorial(self, n):
        if n in self.memo:
            return self.memo[n]
        self.memo[n] = n * self._recursive_factorial(n - 1)
        return self.memo[n]

    def calculate(self, n):
        if not isinstance(n, int) or n < 0:
            raise ValueError("Input must be a non-negative integer.")
        return self._recursive_factorial(n)

class InputValidator:
    def __init__(self):
        self.error_message = "Invalid input"

    def is_valid_integer(self, value):
        return isinstance(value, int)

    def is_non_negative(self, value):
        return value >= 0

    def validate(self, n):
        if not self.is_valid_integer(n):
            raise TypeError("Input must be an integer.")
        if not self.is_non_negative(n):
            raise ValueError("Input must be non-negative.")
        return True

class ResultFormatter:
    def __init__(self):
        self.prefix = "Factorial of"
        self.infix = "is"
        self.suffix = "."

    def format_result(self, number, factorial_value):
        return f"{self.prefix} {number} {self.infix} {factorial_value}{self.suffix}"

    def get_prefix(self):
        return self.prefix

    def get_infix(self):
        return self.infix

    def get_suffix(self):
        return self.suffix

def calculate_factorial(n):
    validator = InputValidator()
    calculator = FactorialCalculator()
    formatter = ResultFormatter()

    validator.validate(n)
    result = calculator.calculate(n)
    return result

